head.script:
/**
* PSP007P01.xml(소송비용 계산)
*
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.19.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/

/* ==================================
 * 1.전역변수 선언부
 * ==================================*/
scwin.localVariable = {
	wfmArr: [{ "name": "wfm_lwstTypeCalcGuide", "src": "/psp/ui/psp000/PSP007F01.xml", "isInitLoaded": true },
	{ "name": "wfm_vsmlClclt", "src": "/psp/ui/psp000/PSP007F02.xml", "isInitLoaded": false },
	{ "name": "wfm_stmpAmtCalc", "src": "/psp/ui/psp000/PSP007F03.xml", "isInitLoaded": false },
	{ "name": "wfm_hskpFeeCalc", "src": "/psp/ui/psp000/PSP007F04.xml", "isInitLoaded": false },
	{ "name": "wfm_dlvrChrgCalc", "src": "/psp/ui/psp000/PSP007F05.xml", "isInitLoaded": false }],

	subFrameParam: {
		"dataObject": {
			"type": "json",
			"name": "wframeParam",
			"data": { "pPgmId": "PSP007P01" } //실제 하위 프레임에 전달되는 파라미터 객체
		}
	},

	isInit: true,
	isClick: false,

}
//이전페이지로부터 전달받은 param
scwin.wfparam = null;

/* ================================== 
* 2.페이지 Onload/Unload 선언부  
* ==================================*/
/**
 * 화면 pageload 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function () {
	scglblo.setCtxtPath("/psp");
	scwin.wfparam = $p.getParameter("paramData");
	if (!scutilo.isEmpty(scwin.wfparam)){
		dma_parentInfo.setJSON(scwin.wfparam.dma_paramData);
	}
	if (!scutilo.isEmpty(dma_parentInfo.get("initTabIdx"))) {
		tac_select.setSelectedTabIndex(dma_parentInfo.get("initTabIdx"));
	} else {
		scwin.localVariable.isInit = false;
		scwin.localVariable.isClick = true;
	}
};


scwin.isMain = function() {
    return true;
};

/**
 * 화면 onpageunload 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageunload = function () {

};

/* ================================== 
* 4.컴포넌트 이벤트 처리부
* ==================================*/

/**
* 상단 탭 onbeforeselect event
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.tac_select_onbeforeselect = function (selectedIndex, index) {
	var wfmObj = scwin.getSelectedFrame(selectedIndex);
	if (scwin.localVariable.isInit) {
		scwin.localVariable.isInit = false;
		scwin.localVariable.isClick = true;
	} else {
		if (scwin.localVariable.isClick) {
			dma_parentInfo.setEmptyValue();
			var param = wfmObj.scope.dma_parentInfo.getJSON();
			//소가산정 탭을 클릭한 경우
			if (index == 1) {
				dma_parentInfo.setJSON(param);
				//인지액 계산 탭에서 진입시
				if (selectedIndex == 2 && index == 1) {
					dma_parentInfo.set("isStmpInfoSetYn", "N");
				}
			} else {//그 외 탭 이동시
				dma_parentInfo.setJSON(
					{
						"elctnLwstTaskTypCd": param.elctnLwstTaskTypCd,
						"openerInputId": param.openerInputId,
					}
				)
				//소가산정 탭에서 인지액 계산 탭으로 이동시
				if (selectedIndex == 1 && index == 2) {
					dma_parentInfo.set("ofdocDvsCd", param.ofdocDvsCd);
				}
			}
		} else {
			scwin.localVariable.isClick = true;
		}
		var wfmArr = scwin.localVariable.wfmArr;
		var wfmObj = scwin.getSelectedFrame(index);
		//탭 reload를 위한 스크립트
		wfmObj.setSrc(wfmArr[index].src, scwin.localVariable.subFrameParam);
	}
};

/**
 * 소송비용계산 중분류 TabControl onchange Event
 * 최초 load가 아닐시 수동으로 서브프레임에 해당화면을 setting한다.
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */

scwin.tac_select_onchange = function (tabID, idx, userTabID) {
	var wfmArr = scwin.localVariable.wfmArr;
	if (!wfmArr[idx].isInitLoaded) {
		wfmArr[idx].isInitLoaded = true;
	}
};

/**
 * 닫기 버튼 onclick event
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_close_onclick = function (e) {
	com.win.closePopup();
};

/* ================================== 
* 5. 사용자 정의 이벤트
* ==================================*/

/**
 * 탭으로부터 paramData 받아서 세팅하는 Method
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.setParentInfo = function (paramData) {
	//Object.keys(data).forEach(function (key)) : object 형태의 data의 key에 대하여 loop를 돌며 로직을 수행한다.
	Object.keys(paramData).forEach(function (key) {
		if (key == "dma_parentInfo") {
			dma_parentInfo.setJSON(paramData[key]);
		} else {
			scwin.localVariable[key] = paramData[key];
		}
	});
}

/**
 * Id로 Opener 창의 변수 object 접근Method
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getOpenerComponent = function (componentId) {
	return opener ? opener.$p.comp[componentId] : parent.$p.comp[componentId];
}

/**
 * 탭으로부터 결과계산 값 받아서 세팅하는 Method(소가산정)
 * 부모창에서 호출시 건네받은 componentId로 해당 component를 찾아서 값을 건네주고 팝업창을 닫는다.
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.setOpenerInputValue = function (result) {
	var compId = dma_parentInfo.get("openerInputId");
	var openerObj = scwin.getOpenerComponent(compId);
	openerObj.setValue(result);
	openerObj.focus();
	com.win.closePopup();
}

/**
 * 자식 탭으로부터 호출하고자 하는 함수를 parameter에 따라 호출하는 Method
 *   - setValue : scwin.setOpenerInputValue Method 호출
 *   - modifyParam : scwin.setParentInfo Method 호출
 *   - movePage : tac_select.setSelectedTabIndex Method 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.fnCalledFromChild = function (flag, param) {
	switch (flag) {
		case "setValue":
			scwin.setOpenerInputValue(param);
			break;
		case "modifyParam":
			scwin.setParentInfo(param);
			break;
		case "movePage":
			tac_select.setSelectedTabIndex(param);
			break;
	}
}

/**
* 현재 화면에 나오는 탭의 content Object를 반환하는 Method
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.19.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getSelectedFrame = function (idx) {
	var wfmObj;
	switch (idx) {
		case 0:
			wfmObj = wfm_lwstTypeCalcGuide;
			break;
		case 1:
			wfmObj = wfm_vsmlClclt;
			break;
		case 2:
			wfmObj = wfm_stmpAmtCalc;
			break;
		case 3:
			wfmObj = wfm_hskpFeeCalc;
			break;
		case 4:
			wfmObj = wfm_dlvrChrgCalc;
			break;
	}
	return wfmObj;
}
